<script lang="ts">
 import {onMount} from 'svelte';
 type Request=(path:string,method?:string,body?:unknown)=>Promise<unknown>;
 type Row={run_id:string;instrument:string;synthetic:boolean;dataset_hash:string;counts:Record<string,number>;source_structural_status:string;calendar_status:string;profile_status:string;requested_period_status:string;historical_admission:boolean};
 type Attempt={attempt_id:string;outcome:string;rows_scanned:number;error:string|null;resources_json:string};
 type Report={run_id:string;synthetic:boolean;inputs:{dataset_hash:string;code_revision:string;calendar_hash:string|null;profile_hash:string|null};instrument:string;complete_source_scan:boolean;counts:Record<string,number>;calendar_status:string;profile_status:string;requested_period_status:string;historical_admission:boolean;source_structural_status:string;scope:string;events_sha256:string;events_bytes:number};
 let {request,download}:{request:Request;download:(path:string,name:string)=>Promise<void>}=$props();
 let rows=$state<Row[]>([]),attempts=$state<Attempt[]>([]),report=$state<Report|null>(null),busy=$state(false),error=$state('');
 async function refresh(){busy=true;error='';try{[rows,attempts]=await Promise.all([request('data/quality'),request('data/quality-attempts')]) as [Row[],Attempt[]];}catch(e){error=String(e);}finally{busy=false;}}
 async function inspect(id:string){busy=true;error='';try{report=await request('data/quality/'+id) as Report;}catch(e){error=String(e);report=null;}finally{busy=false;}}
 onMount(()=>{void refresh();});
</script>
<section class="quality" aria-label="Source quality evidence">
 <header><div><h2>Source quality evidence</h2><p>Full source scans retain every reported gap and issue. The displayed examples are bounded; the event artifact retains the complete record.</p></div><button disabled={busy} onclick={refresh}>Refresh source evidence</button></header>
 <p class="warning">A structural pass or declared calendar does not verify broker facts or prove complete market coverage. Dated profile, calendar and source acceptance remain required.</p>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 {#if busy}<p role="status">Checking source evidence…</p>{/if}
 {#if !rows.length}<p>No completed source-quality receipts.</p>{/if}
 {#each rows as row}<article><div><h3>{row.instrument} · {row.source_structural_status} · {row.synthetic?'Synthetic fixture':'Historical source'}</h3><p>{row.counts.rows_scanned.toLocaleString()} quotes · {row.counts.gaps??0} internal gaps · {row.counts.boundary_intervals??0} boundary intervals</p><p>Calendar: {row.calendar_status}<br/>Instrument: {row.profile_status}<br/>Requested period: {row.requested_period_status}<br/>Historical admission: <strong>{row.historical_admission?'allowed':'blocked'}</strong></p><code>{row.run_id}</code></div><button disabled={busy} onclick={()=>inspect(row.run_id)}>Inspect source {row.run_id.slice(0,8)}</button></article>{/each}
 {#if report}<section><h3>{report.instrument} scan receipt</h3><p>{report.synthetic?'Synthetic software fixture':'Historical source integrity evidence'}. {report.scope}</p><p>Full source scan: {report.complete_source_scan?'complete':'incomplete'} · expected source period: {report.requested_period_status} · historical admission: {report.historical_admission?'allowed':'blocked'}.</p><p>Dataset <code>{report.inputs.dataset_hash}</code></p><p>Code <code>{report.inputs.code_revision}</code></p><dl>{#each Object.entries(report.counts) as [name,value]}<dt>{name.replaceAll('_',' ')}</dt><dd>{value.toLocaleString()}</dd>{/each}</dl><p>Complete event artifact: {report.events_bytes.toLocaleString()} bytes · SHA256 <code>{report.events_sha256}</code>.</p><div class="actions"><button onclick={()=>download('data/quality/'+report!.run_id,'source-quality-'+report!.run_id+'.json')}>Download exact scan receipt</button><button onclick={()=>download('data/quality/'+report!.run_id+'/events','source-quality-'+report!.run_id+'.jsonl')}>Download all gap and issue events</button></div><p>Canonical quote values and order are unchanged. Unknown calendars and unreviewed units remain unknown.</p></section>{/if}
 <details><summary>Source scan attempts and failures</summary>{#if !attempts.length}<p>No scan attempts.</p>{/if}{#each attempts as attempt}<article><div><strong>{attempt.outcome}</strong><p>{attempt.rows_scanned.toLocaleString()} rows scanned{attempt.outcome==='FAILED_INCOMPLETE'?' · incomplete evidence':''}</p>{#if attempt.error}<p class="error">{attempt.error}</p>{/if}<p>{Number(JSON.parse(attempt.resources_json).wall_seconds).toFixed(2)} seconds wall time · {Number(JSON.parse(attempt.resources_json).cpu_seconds).toFixed(2)} CPU seconds</p></div></article>{/each}</details>
</section>
<style>
 .quality{padding:22px;background:#151d29;border:1px solid #293447;border-radius:12px;margin-bottom:22px;min-width:0}header,article{display:flex;justify-content:space-between;align-items:start;gap:16px}article{border-top:1px solid #293447;padding:16px 0}h2{font-size:19px}h3{font-size:16px}p{line-height:1.6;color:#b6c2d2}.warning{color:#e5c37c;border-left:3px solid;padding-left:14px}.error{color:#ffa69e}code{font-size:12px;overflow-wrap:anywhere}button{font:inherit;border:1px solid #3a4b61;border-radius:7px;padding:10px;background:#1c293b;color:#e3e8f0;cursor:pointer;max-width:100%}button:disabled{opacity:.5}section{border-top:1px solid #293447;margin-top:20px;padding-top:10px}dl{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px}dt{overflow-wrap:anywhere}dd{margin:0}.actions{display:flex;flex-wrap:wrap;gap:12px}summary{cursor:pointer;margin-top:20px}@media(max-width:760px){header,article{display:block}.quality{padding:16px}}
</style>
